//! Parity with the Python implementation through golden vectors generated by
//! `apps/backend/tests-golden/server/gen_server.py` (run against `apps/api`).

mod common;

use serde_json::Value;
use ss_core::Contract;
use ss_server::contracts::{payload_hash, ApprovalRequest};
use ss_server::error::AppError;
use ss_server::{pyjson, security};
use uuid::Uuid;

use common::golden;

/// Python answered these with a 500 (`TypeError` / `ValueError` escaping `verify_*`); Rust
/// answers 401. Everything else must match Python exactly.
const PYTHON_500: [&str; 3] = [
    "non_ascii_signature",
    "signed_non_int_exp",
    "signed_bad_uuid",
];

fn check(name: &str, python: &Value, rust: Result<String, AppError>) {
    match (python.get("ok"), rust) {
        (Some(ok), Ok(got)) => assert_eq!(got, ok.as_str().unwrap(), "{name}"),
        (Some(ok), Err(e)) => panic!("{name}: Python accepted ({ok}), Rust refused: {e}"),
        (None, Ok(got)) => panic!("{name}: Python refused ({python}), Rust accepted: {got}"),
        (None, Err(e)) => {
            assert_eq!(
                e.status().as_u16(),
                401,
                "{name}: every malformed token is a 401"
            );
            assert_eq!(e.error_code(), "UNAUTHORIZED", "{name}");
            if python["error"] == "UnauthorizedError" {
                assert_eq!(e.to_string(), python["message"].as_str().unwrap(), "{name}");
            } else {
                assert!(
                    PYTHON_500.contains(&name),
                    "{name}: unexpected Python error {python}"
                );
            }
        }
    }
}

#[test]
fn tokens_match_python() {
    let g = golden("tokens.json");
    let secret = g["secret"].as_str().unwrap();
    for case in g["issue"].as_array().unwrap() {
        let user: Uuid = case["user_id"].as_str().unwrap().parse().unwrap();
        let tok = security::issue_token_at(
            secret,
            user,
            case["purpose"].as_str().unwrap(),
            case["exp"].as_i64().unwrap(),
        );
        assert_eq!(tok, case["token"].as_str().unwrap());
    }
    let mut python_500 = Vec::new();
    for case in g["verify"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let rust = security::verify_token_at(
            secret,
            case["token"].as_str().unwrap(),
            case["purpose"].as_str().unwrap(),
            case["now"].as_f64().unwrap(),
        )
        .map(|u| u.to_string());
        check(name, &case["python"], rust);
        if case["python"]["error"]
            .as_str()
            .is_some_and(|e| e != "UnauthorizedError")
        {
            python_500.push(name);
        }
    }
    for case in g["media_sign"].as_array().unwrap() {
        let tok = security::sign_media_key_at(
            secret,
            case["key"].as_str().unwrap(),
            case["exp"].as_i64().unwrap(),
        );
        assert_eq!(tok, case["token"].as_str().unwrap());
    }
    for case in g["media_verify"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let rust = security::verify_media_key_at(
            secret,
            case["token"].as_str().unwrap(),
            case["now"].as_f64().unwrap(),
        );
        check(name, &case["python"], rust);
        if case["python"]["error"]
            .as_str()
            .is_some_and(|e| e != "UnauthorizedError")
        {
            python_500.push(name);
        }
    }
    // The Python defects are the ones documented, no more.
    python_500.sort();
    assert_eq!(
        python_500,
        [
            "non_ascii_signature",
            "non_ascii_signature",
            "signed_bad_uuid",
            "signed_non_int_exp",
            "signed_non_int_exp"
        ]
    );
    // Tokens minted here verify in the Python vectors' format and vice versa (round trip).
    let user = Uuid::new_v4();
    let tok = security::issue_token(secret, user);
    assert_eq!(
        security::verify_token(secret, &tok, "access").unwrap(),
        user
    );
}

#[test]
fn payload_hash_matches_python() {
    let vectors = golden("payload_hash.json");
    let mut checked = 0;
    let mut unsupported = Vec::new();
    for v in vectors.as_array().unwrap() {
        let name = v["name"].as_str().unwrap();
        if !v["rust_supported"].as_bool().unwrap() {
            unsupported.push(name);
            continue;
        }
        let payload: Value = serde_json::from_str(v["payload_json"].as_str().unwrap()).unwrap();
        assert_eq!(
            pyjson::dumps_canonical(&payload),
            v["canonical"].as_str().unwrap(),
            "{name}"
        );
        let Value::Object(map) = payload else {
            panic!("{name}")
        };
        assert_eq!(payload_hash(&map), v["hash"].as_str().unwrap(), "{name}");
        checked += 1;
    }
    // Known serde_json limits (documented in the report): integers beyond u64 and the integer
    // literal `-0`. Our own payloads never contain either.
    assert_eq!(
        unsupported,
        ["big_int_beyond_u64", "negative_zero_integer_literal"]
    );
    assert_eq!(checked, vectors.as_array().unwrap().len() - 2);
}

#[test]
fn approval_request_matches_pydantic() {
    let g = golden("approval.json");
    // A stored document keeps its hash.
    let a = ApprovalRequest::from_json_value(g["dump"].clone()).unwrap();
    assert_eq!(serde_json::to_value(&a).unwrap(), g["dump"]);
    // Without a hash, model_post_init computes the same one Python computed.
    let b = ApprovalRequest::from_json_value(g["without_hash"].clone()).unwrap();
    assert_eq!(
        b.action_payload_hash,
        g["dump"]["action_payload_hash"].as_str().unwrap()
    );
    assert_eq!(serde_json::to_value(&b).unwrap(), g["dump"]);
    let mut extra = g["dump"].clone();
    extra["surprise"] = Value::Bool(true);
    assert!(
        ApprovalRequest::from_json_value(extra).is_err(),
        "extra fields are rejected"
    );
}

/// The shipped binary must parse floats exactly as Python does, or `payload_hash` differs between
/// the backends (about 1 in 5 computed values such as square-feet-to-m2 areas were misparsed by
/// one ULP). serde_json's `float_roundtrip` feature must therefore be enabled by a normal
/// dependency: the `jsonschema` dev-dependency enables it in test builds only, which hid the
/// mismatch from every test in this crate.
#[test]
fn float_roundtrip_is_a_normal_dependency_feature() {
    let manifest = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/Cargo.toml"))
        .expect("Cargo.toml");
    let normal = manifest
        .split("[dev-dependencies]")
        .next()
        .expect("manifest");
    let line = normal
        .lines()
        .find(|l| l.trim_start().starts_with("serde_json"))
        .expect("serde_json dependency");
    assert!(line.contains("float_roundtrip"), "{line}");
}

/// Hashes computed by Python's `payload_hash(json.loads(text))`: values the production build
/// misparsed without `float_roundtrip`, decimal ties `float_repr` broke the wrong way, and a
/// subnormal that only correct rounding gets right.
#[test]
fn payload_hash_float_edges_match_python() {
    let cases = [
        (
            r#"{"area_m2": 110.64752064000001, "lat": 12.917521550408111, "lng": 113.80548928321133}"#,
            "69231a6d3308ef3b649f493dd8b4515e3ae4d195c0f070f562d413f41de9333c",
        ),
        (
            r#"{"x": 1682373064852680.2, "y": [26363981746409.312, -1425502010969177.2]}"#,
            "4cd4c8d79213749bd224e6cbd86e61b6b1780ea604f592616e7e1355edec82c3",
        ),
        (
            r#"{"tiny": 2.4703282292062328e-324}"#,
            "1bbcf787442fe47a23ad1d57601bd1e9f003db55473cb08e38d0c3bf19da8409",
        ),
    ];
    for (text, want) in cases {
        let Value::Object(map) = serde_json::from_str::<Value>(text).unwrap() else {
            panic!("{text}")
        };
        assert_eq!(payload_hash(&map), want, "{text}");
    }
}
